/**
 * Right-world scenery render pass for the neatRacing example
 * (plan slices P1-right-world-props, P1-neatenstein-public, P1-mechanic-crew,
 * and P1-decoration-scale; Step 14D; AC-048 + AC-049 + AC-050 + AC-051).
 *
 * Draws the TRON-style neon scenery props generated by
 * {@link buildRightWorldProps} after the track slab pass so they sit on top of
 * the ground plane and behind the car glass pass, then overlays the recycled
 * Neatenstein public/agent and mechanic-crew billboard sprites produced by
 * {@link buildPublicBillboards} and {@link buildMechanicBillboards}.
 *
 * The billboard `quad` fields carried by the sprite helpers are expressed in
 * projection-space units (focal * dot / distance), not screen pixels. The pass
 * ignores those precomputed quads and rebuilds world-space camera-facing
 * billboard geometry each frame from the chase camera, so the unit system stays
 * consistent with the WebGL vertex path (OBS-26 reconciled).
 *
 * Both sprite modules export their own distance-aware scale helpers with the
 * same constants; the pass uses the public helper `computeBillboardScale` for
 * all billboards to keep the upload loop single and avoid duplicating the formula.
 *
 * The pass compiles two WebGL2 programs (solid props + textured billboards),
 * uploads a single packed sprite atlas, and draws camera-facing billboards
 * each frame without allocating new JavaScript objects on the steady-state
 * path. All mutable draw state is refreshed in-place from the frame supplied
 * by the host.
 */

import { buildRightWorldProps } from './right-world.builder';
import type { RightWorldProp } from './right-world.builder';
import { resolvePropHalfSize } from './right-world.prop-sizes';
import {
  NEATRACING_DECORATION_CULL_DISTANCE_M,
  NEATRACING_DECORATION_LOD_BUDGET,
  createDecorationSelectionScratch,
  selectVisibleDecorationsForCamera,
} from './decoration.lod';
import type { DecorationSelectionScratch } from './decoration.lod';
import {
  buildPublicBillboards,
  computeBillboardScale,
  computePublicRuntimeFrameIndex,
  DIRECTION_ORDER,
  loadPublicSpriteAtlas,
  PUBLIC_POSE_COUNT,
  PUBLIC_POSE_INDEX_STAND,
  PUBLIC_POSE_INDEX_WALK1,
  PUBLIC_POSE_INDEX_WALK2,
} from './public.sprite';
import type {
  PublicBillboard,
  PublicCamera,
  PublicSpriteFrame,
} from './public.sprite';
import {
  buildMechanicBillboards,
  computeMechanicRuntimeFrameIndex,
  loadMechanicSpriteAtlas,
} from './mechanic.sprite';
import type {
  MechanicBillboard,
  MechanicSpriteFrame,
} from './mechanic.sprite';
import type { TrackSlabBuildInput } from './track.slabs';

/** Determinism tuple shared with the track slab and right-world builders. */
const NEATRACING_RIGHT_WORLD_BUILD_INPUT = {
  seed: 42,
  layoutVersion: 1,
  sizeBucket: 'large',
} as const satisfies TrackSlabBuildInput;

/**
 * Canonical camera used only to obtain world-space billboard positions and
 * frame ids. The precomputed screen-space quads are ignored by the pass, which
 * rebuilds world-space camera-facing quads each frame from the chase camera.
 */
const DEFAULT_RIGHT_WORLD_CAMERA: PublicCamera = {
  position: [0, 2, 20],
  forward: [0, -0.1, -1],
  right: [1, 0, 0],
  near: 0.1,
  far: 200,
  fovDegrees: 60,
};

/** Meters per sprite pixel applied to the distance-aware screen-space scale. */
const NEATRACING_BILLBOARD_WORLD_PIXEL_SCALE = 0.05;

/** Vertex shader shared by the solid prop program. */
const NEATRACING_RIGHT_WORLD_PROP_VERTEX_SHADER = `#version 300 es
precision highp float;
layout(location = 0) in vec3 a_position;
layout(location = 1) in vec3 a_color;
uniform mat4 u_viewProjection;
out vec3 v_color;
void main() {
  gl_Position = u_viewProjection * vec4(a_position, 1.0);
  v_color = a_color;
}
`;

/** Fragment shader shared by the solid prop program. */
const NEATRACING_RIGHT_WORLD_PROP_FRAGMENT_SHADER = `#version 300 es
precision mediump float;
in vec3 v_color;
out vec4 fragColor;
void main() {
  fragColor = vec4(v_color, 1.0);
}
`;

/** Vertex shader for the textured billboard program. */
const NEATRACING_RIGHT_WORLD_BILLBOARD_VERTEX_SHADER = `#version 300 es
precision highp float;
layout(location = 0) in vec3 a_position;
layout(location = 1) in vec2 a_uv;
uniform mat4 u_viewProjection;
out vec2 v_uv;
void main() {
  gl_Position = u_viewProjection * vec4(a_position, 1.0);
  v_uv = a_uv;
}
`;

/** Fragment shader for the textured billboard program. */
const NEATRACING_RIGHT_WORLD_BILLBOARD_FRAGMENT_SHADER = `#version 300 es
precision mediump float;
in vec2 v_uv;
uniform sampler2D u_atlas;
out vec4 fragColor;
void main() {
  fragColor = texture(u_atlas, v_uv);
}
`;

/** Floats per prop vertex: position (3) + color (3). */
const PROP_FLOATS_PER_VERTEX = 6;

/** Floats per billboard vertex: position (3) + uv (2). */
const BILLBOARD_FLOATS_PER_VERTEX = 5;

/** Vertices emitted for one axis-aligned box (12 triangles). */
const VERTICES_PER_BOX = 36;

/** Floats emitted for one prop box. */
const FLOATS_PER_BOX = VERTICES_PER_BOX * PROP_FLOATS_PER_VERTEX;

/** Maximum number of opaque props selected per frame (shared budget). */
const MAX_PROPS = NEATRACING_DECORATION_LOD_BUDGET;

/** Maximum number of translucent billboards selected per frame (shared budget). */
const MAX_BILLBOARDS = NEATRACING_DECORATION_LOD_BUDGET;

/** UV rectangle for one sprite frame inside the packed atlas. */
interface SpriteFrameUv {
  readonly u0: number;
  readonly v0: number;
  readonly u1: number;
  readonly v1: number;
}

/** Sprite frame shape shared by public and mechanic atlases. */
type RightWorldSpriteFrame = PublicSpriteFrame | MechanicSpriteFrame;

/** Sprite atlas shape shared by public and mechanic sources. */
interface RightWorldSpriteAtlas {
  readonly source: string;
  readonly frames: readonly RightWorldSpriteFrame[];
}

/** Billboard shape shared by public and mechanic emitters. */
type RightWorldBillboard = PublicBillboard | MechanicBillboard;

/** CPU-side scene data consumed by the right-world pass. */
export interface RightWorldSceneData {
  readonly props: readonly RightWorldProp[];
  readonly atlas: RightWorldSpriteAtlas;
  readonly billboards: readonly RightWorldBillboard[];
}

/** Mutable frame draw state forwarded to {@link RightWorldPass.draw}. */
export interface RightWorldPassDrawState {
  /** Column-major 4x4 view-projection matrix in meters. */
  viewProjection: Float32Array;
  /** Camera world position in meters. */
  cameraWorld: [number, number, number];
  /** Normalized camera-right basis vector. */
  cameraRight: [number, number, number];
  /** Normalized camera-up basis vector. */
  cameraUp: [number, number, number];
  /** Monotonic frame time in seconds for animated walk poses. */
  timeSeconds: number;
  /** Live car world position for look-at-car gaze. Defaults to cameraWorld. */
  carPosition?: readonly [number, number, number];
}

/** Handle to the compiled right-world scenery draw pass. */
export interface RightWorldPass {
  draw: (state: RightWorldPassDrawState) => void;
  dispose: () => void;
}

/**
 * Builds the deterministic CPU-side scene data once: TRON props plus the
 * recycled public/agent and mechanic-crew billboard lists. The billboard
 * screen-space quads are ignored; only world positions and frame ids are
 * retained by the pass. The two source atlases are packed into one combined
 * atlas so the existing single-texture billboard draw path can render both.
 *
 * The default right-world camera position is wired through
 * `buildPublicBillboards` and `buildMechanicBillboards` so the 8-direction
 * sprite frame selection is relative to the same heading used in the red tests.
 *
 * @returns Scene data ready to upload to the GPU pass.
 */
export function buildRightWorldSceneData(): RightWorldSceneData {
  const props = buildRightWorldProps(NEATRACING_RIGHT_WORLD_BUILD_INPUT);
  const publicAtlas = loadPublicSpriteAtlas();
  const mechanicAtlas = loadMechanicSpriteAtlas();
  const atlas: RightWorldSpriteAtlas = {
    source: 'neatenstein-public+mechanic',
    frames: [...publicAtlas.frames, ...mechanicAtlas.frames],
  };
  const publicBillboards = buildPublicBillboards(
    NEATRACING_RIGHT_WORLD_BUILD_INPUT,
    DEFAULT_RIGHT_WORLD_CAMERA,
    publicAtlas,
  );
  const mechanicBillboards = buildMechanicBillboards(
    NEATRACING_RIGHT_WORLD_BUILD_INPUT,
    DEFAULT_RIGHT_WORLD_CAMERA,
    mechanicAtlas,
  );

  return {
    props,
    atlas,
    billboards: [...publicBillboards, ...mechanicBillboards],
  };
}

/**
 * Writes one axis-aligned box into an interleaved position+color VBO target.
 * The box is centered at the prop position with its base on the y=0 plane.
 *
 * @param target - Preallocated Float32Array to write into.
 * @param offset - Float offset into `target`.
 * @param prop - Scenery prop to emit.
 * @returns The number of floats written.
 */
function emitPropBox(
  target: Float32Array,
  offset: number,
  prop: RightWorldProp,
): number {
  const [px, py, pz] = prop.position;
  const [hx, hy, hz] = resolvePropHalfSize(prop.kind);
  const centerY = py + hy;
  const color = [
    prop.color[0] / 255,
    prop.color[1] / 255,
    prop.color[2] / 255,
  ] as const;

  const positions: readonly (readonly [number, number, number])[] = [
    // Front face (+z)
    [px - hx, centerY - hy, pz + hz],
    [px + hx, centerY - hy, pz + hz],
    [px + hx, centerY + hy, pz + hz],
    [px - hx, centerY - hy, pz + hz],
    [px + hx, centerY + hy, pz + hz],
    [px - hx, centerY + hy, pz + hz],
    // Back face (-z)
    [px + hx, centerY - hy, pz - hz],
    [px - hx, centerY - hy, pz - hz],
    [px - hx, centerY + hy, pz - hz],
    [px + hx, centerY - hy, pz - hz],
    [px - hx, centerY + hy, pz - hz],
    [px + hx, centerY + hy, pz - hz],
    // Right face (+x)
    [px + hx, centerY - hy, pz + hz],
    [px + hx, centerY - hy, pz - hz],
    [px + hx, centerY + hy, pz - hz],
    [px + hx, centerY - hy, pz + hz],
    [px + hx, centerY + hy, pz - hz],
    [px + hx, centerY + hy, pz + hz],
    // Left face (-x)
    [px - hx, centerY - hy, pz - hz],
    [px - hx, centerY - hy, pz + hz],
    [px - hx, centerY + hy, pz + hz],
    [px - hx, centerY - hy, pz - hz],
    [px - hx, centerY + hy, pz + hz],
    [px - hx, centerY + hy, pz - hz],
    // Top face (+y)
    [px - hx, centerY + hy, pz + hz],
    [px + hx, centerY + hy, pz + hz],
    [px + hx, centerY + hy, pz - hz],
    [px - hx, centerY + hy, pz + hz],
    [px + hx, centerY + hy, pz - hz],
    [px - hx, centerY + hy, pz - hz],
    // Bottom face (-y)
    [px - hx, centerY - hy, pz - hz],
    [px + hx, centerY - hy, pz - hz],
    [px + hx, centerY - hy, pz + hz],
    [px - hx, centerY - hy, pz - hz],
    [px + hx, centerY - hy, pz + hz],
    [px - hx, centerY - hy, pz + hz],
  ];

  let written = 0;
  for (const [x, y, z] of positions) {
    target[offset + written] = x;
    written += 1;
    target[offset + written] = y;
    written += 1;
    target[offset + written] = z;
    written += 1;
    target[offset + written] = color[0];
    written += 1;
    target[offset + written] = color[1];
    written += 1;
    target[offset + written] = color[2];
    written += 1;
  }

  return written;
}

/**
 * Packs the public sprite atlas frames into a single RGBA texture and computes
 * per-frame UV rectangles. The layout is a horizontal strip; frames may have
 * different heights, and the atlas height is the tallest frame.
 *
 * @param gl - WebGL2 context to allocate the texture on.
 * @param atlas - Public sprite atlas frames.
 * @returns GPU texture handle, per-frame UV table, and frame-id lookup map.
 */
function buildAtlasTextureAndUvs(
  gl: WebGL2RenderingContext,
  atlas: RightWorldSpriteAtlas,
): {
  readonly texture: WebGLTexture;
  readonly uvs: readonly SpriteFrameUv[];
  readonly frameIdToIndex: ReadonlyMap<string, number>;
} {
  if (atlas.frames.length === 0) {
    throw new Error(
      'neatRacing right-world pass: combined sprite atlas has no frames',
    );
  }

  let totalWidth = 0;
  let maxHeight = 0;
  for (const frame of atlas.frames) {
    totalWidth += frame.width;
    maxHeight = Math.max(maxHeight, frame.height);
  }

  const data = new Uint8Array(totalWidth * maxHeight * 4);
  const uvs: SpriteFrameUv[] = [];
  const frameIdToIndex = new Map<string, number>();
  let offsetX = 0;
  for (let frameIndex = 0; frameIndex < atlas.frames.length; frameIndex += 1) {
    const frame = atlas.frames[frameIndex]!;
    for (let row = 0; row < frame.height; row += 1) {
      const srcStart = row * frame.width * 4;
      const dstStart = (row * totalWidth + offsetX) * 4;
      data.set(
        frame.rgba.subarray(srcStart, srcStart + frame.width * 4),
        dstStart,
      );
    }

    uvs.push({
      u0: offsetX / totalWidth,
      v0: 0,
      u1: (offsetX + frame.width) / totalWidth,
      v1: frame.height / maxHeight,
    });
    frameIdToIndex.set(frame.id, frameIndex);
    offsetX += frame.width;
  }

  const texture = gl.createTexture();
  if (!texture) {
    throw new Error('neatRacing right-world pass: createTexture returned null');
  }
  gl.bindTexture(gl.TEXTURE_2D, texture);
  // Atlas orientation contract: decoded frame.rgba stores row 0 at the sprite
  // top, while WebGL's default image origin is the bottom-left. Flip the Y axis
  // during upload so UV v1 maps to the logical top row and v0 maps to the bottom.
  // The previous UNPACK_FLIP_Y_WEBGL value is saved and restored to avoid
  // surprising other passes (OBS-5).
  const previousUnpackFlipY = gl.getParameter(gl.UNPACK_FLIP_Y_WEBGL);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.texImage2D(
    gl.TEXTURE_2D,
    0,
    gl.RGBA,
    totalWidth,
    maxHeight,
    0,
    gl.RGBA,
    gl.UNSIGNED_BYTE,
    data,
  );
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, Number(previousUnpackFlipY));
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);

  return { texture, uvs, frameIdToIndex };
}

/**
 * Compiles one GLSL ES 3.0 shader and throws a descriptive message on failure.
 *
 * @param gl - WebGL2 context.
 * @param type - Shader type enum.
 * @param source - Shader source.
 * @param label - Debug label for error messages.
 * @returns Compiled shader handle.
 */
function compileRightWorldShader(
  gl: WebGL2RenderingContext,
  type: number,
  source: string,
  label: string,
): WebGLShader {
  const shader = gl.createShader(type);
  if (!shader) {
    throw new Error(
      `neatRacing right-world pass: createShader(${label}) returned null`,
    );
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const infoLog = gl.getShaderInfoLog(shader) ?? 'unknown error';
    throw new Error(
      `neatRacing right-world pass: ${label} shader compile failed: ${infoLog}`,
    );
  }
  return shader;
}

/**
 * Links a program from a vertex/fragment shader pair and validates link status.
 *
 * @param gl - WebGL2 context.
 * @param vertexShader - Compiled vertex shader.
 * @param fragmentShader - Compiled fragment shader.
 * @param label - Debug label for error messages.
 * @returns Linked program handle.
 */
function linkRightWorldProgram(
  gl: WebGL2RenderingContext,
  vertexShader: WebGLShader,
  fragmentShader: WebGLShader,
  label: string,
): WebGLProgram {
  const program = gl.createProgram();
  if (!program) {
    throw new Error(
      `neatRacing right-world pass: createProgram(${label}) returned null`,
    );
  }
  gl.attachShader(program, vertexShader);
  gl.attachShader(program, fragmentShader);
  gl.linkProgram(program);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const infoLog = gl.getProgramInfoLog(program) ?? 'unknown error';
    throw new Error(
      `neatRacing right-world pass: ${label} program link failed: ${infoLog}`,
    );
  }
  return program;
}

/**
 * Fills the preallocated billboard upload buffer with camera-facing quads and
 * returns the number of vertices to draw. Frame ids out of range are skipped.
 *
 * @param target - Preallocated Float32Array for position+uv vertices.
 * @param billboards - Billboard instances.
 * @param atlasFrames - Original atlas frames for pixel dimensions.
 * @param uvs - Per-frame UV rectangles inside the packed atlas.
 * @param frameIdToIndex - Map from frame id string to atlas frame index.
 * @param billboardCount - Number of visible billboards already selected into `billboardScratch` (nearest-first).
 * @param billboardScratch - Preallocated selection scratch with indices/distances sorted nearest-first.
 * @param cameraRight - World-space camera right unit vector.
 * @param cameraUp - World-space camera up unit vector.
 * @returns Total number of vertices to draw.
 */
function buildBillboardUpload(
  target: Float32Array,
  billboards: readonly RightWorldBillboard[],
  atlasFrames: readonly RightWorldSpriteFrame[],
  uvs: readonly SpriteFrameUv[],
  frameIdToIndex: ReadonlyMap<string, number>,
  billboardCount: number,
  billboardScratch: DecorationSelectionScratch,
  cameraRight: readonly [number, number, number],
  cameraUp: readonly [number, number, number],
): number {
  const [rx, ry, rz] = cameraRight;
  const [ux, uy, uz] = cameraUp;
  let offset = 0;
  let vertexCount = 0;

  for (let slot = billboardCount - 1; slot >= 0; slot -= 1) {
    const billboard = billboards[billboardScratch.indices[slot]];
    if (!billboard) {
      continue;
    }
    const distance = billboardScratch.distances[slot];
    const frameIndex = frameIdToIndex.get(billboard.frameId);
    if (frameIndex === undefined) {
      continue;
    }
    const frame = atlasFrames[frameIndex];
    const uv = uvs[frameIndex];
    if (!frame || !uv) {
      continue;
    }

    const scale =
      computeBillboardScale(distance) * NEATRACING_BILLBOARD_WORLD_PIXEL_SCALE;
    const halfW = (frame.width * scale) / 2;
    const fullH = frame.height * scale;

    // position is the base/foot anchor; expand upward along cameraUp so the
    // sprite bottom stays at the surface regardless of runtime camera distance.
    const corners: readonly (readonly [number, number, number])[] = [
      [
        billboard.position[0] + rx * -halfW,
        billboard.position[1] + ry * -halfW,
        billboard.position[2] + rz * -halfW,
      ],
      [
        billboard.position[0] + rx * halfW,
        billboard.position[1] + ry * halfW,
        billboard.position[2] + rz * halfW,
      ],
      [
        billboard.position[0] + rx * halfW + ux * fullH,
        billboard.position[1] + ry * halfW + uy * fullH,
        billboard.position[2] + rz * halfW + uz * fullH,
      ],
      [
        billboard.position[0] + rx * -halfW + ux * fullH,
        billboard.position[1] + ry * -halfW + uy * fullH,
        billboard.position[2] + rz * -halfW + uz * fullH,
      ],
    ];

    const positions: readonly (readonly [number, number, number])[] = [
      corners[0],
      corners[1],
      corners[2],
      corners[0],
      corners[2],
      corners[3],
    ];
    const texCoords: readonly (readonly [number, number])[] = [
      [uv.u0, uv.v1],
      [uv.u1, uv.v1],
      [uv.u1, uv.v0],
      [uv.u0, uv.v1],
      [uv.u1, uv.v0],
      [uv.u0, uv.v0],
    ];

    for (let index = 0; index < positions.length; index += 1) {
      const [x, y, z] = positions[index]!;
      const [u, v] = texCoords[index]!;
      target[offset] = x;
      target[offset + 1] = y;
      target[offset + 2] = z;
      target[offset + 3] = u;
      target[offset + 4] = v;
      offset += BILLBOARD_FLOATS_PER_VERTEX;
      vertexCount += 1;
    }
  }

  return vertexCount;
}

/**
 * Creates the right-world scenery draw pass: compiles shaders, builds the
 * deterministic CPU-side scene data, packs the public sprite atlas, and
 * preallocates dynamic prop and billboard VBOs. The returned handle selects
 * visible props each frame against the runtime camera (opaque, depth-write)
 * and then draws blended billboards far-to-near (depth-read, no depth-write)
 * without allocating JavaScript objects on the steady-state path.
 *
 * @param gl - WebGL2 rendering context.
 * @returns The right-world pass handle.
 */
export function createRightWorldPass(
  gl: WebGL2RenderingContext,
): RightWorldPass {
  const scene = buildRightWorldSceneData();

  const propVertexShader = compileRightWorldShader(
    gl,
    gl.VERTEX_SHADER,
    NEATRACING_RIGHT_WORLD_PROP_VERTEX_SHADER,
    'prop vertex',
  );
  const propFragmentShader = compileRightWorldShader(
    gl,
    gl.FRAGMENT_SHADER,
    NEATRACING_RIGHT_WORLD_PROP_FRAGMENT_SHADER,
    'prop fragment',
  );
  const propProgram = linkRightWorldProgram(
    gl,
    propVertexShader,
    propFragmentShader,
    'prop',
  );
  const propViewProjectionLoc = gl.getUniformLocation(
    propProgram,
    'u_viewProjection',
  );

  const billboardVertexShader = compileRightWorldShader(
    gl,
    gl.VERTEX_SHADER,
    NEATRACING_RIGHT_WORLD_BILLBOARD_VERTEX_SHADER,
    'billboard vertex',
  );
  const billboardFragmentShader = compileRightWorldShader(
    gl,
    gl.FRAGMENT_SHADER,
    NEATRACING_RIGHT_WORLD_BILLBOARD_FRAGMENT_SHADER,
    'billboard fragment',
  );
  const billboardProgram = linkRightWorldProgram(
    gl,
    billboardVertexShader,
    billboardFragmentShader,
    'billboard',
  );
  const billboardViewProjectionLoc = gl.getUniformLocation(
    billboardProgram,
    'u_viewProjection',
  );
  const billboardAtlasLoc = gl.getUniformLocation(
    billboardProgram,
    'u_atlas',
  );

  const propVbo = gl.createBuffer();
  if (!propVbo) {
    throw new Error('neatRacing right-world pass: createBuffer(prop) returned null');
  }
  const propUpload = new Float32Array(
    Math.max(1, scene.props.length * FLOATS_PER_BOX),
  );
  gl.bindBuffer(gl.ARRAY_BUFFER, propVbo);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    Math.max(1, scene.props.length * FLOATS_PER_BOX * 4),
    gl.DYNAMIC_DRAW,
  );

  const billboardVbo = gl.createBuffer();
  if (!billboardVbo) {
    throw new Error('neatRacing right-world pass: createBuffer(billboard) returned null');
  }
  gl.bindBuffer(gl.ARRAY_BUFFER, billboardVbo);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    MAX_BILLBOARDS * 6 * BILLBOARD_FLOATS_PER_VERTEX * 4,
    gl.DYNAMIC_DRAW,
  );

  const {
    texture: atlasTexture,
    uvs,
    frameIdToIndex,
  } = buildAtlasTextureAndUvs(gl, scene.atlas);

  const billboardUpload = new Float32Array(
    MAX_BILLBOARDS * 6 * BILLBOARD_FLOATS_PER_VERTEX,
  );
  const propScratch = createDecorationSelectionScratch(scene.props.length);
  const billboardScratch = createDecorationSelectionScratch(
    scene.billboards.length,
  );

  return {
    draw: (state): void => {
      // Defensive: this pass mixes solid props with camera-facing billboard
      // quads that are double-sided by design. Disable face culling so a sprite
      // viewed from behind is not dropped (OBS-4).
      gl.disable(gl.CULL_FACE);

      // Opaque scenery props: cull against runtime camera, nearest first.
      const visiblePropCount = selectVisibleDecorationsForCamera(
        scene.props,
        state.cameraWorld,
        NEATRACING_DECORATION_CULL_DISTANCE_M,
        MAX_PROPS,
        propScratch,
      );
      let propFloatOffset = 0;
      for (let slot = 0; slot < visiblePropCount; slot += 1) {
        const prop = scene.props[propScratch.indices[slot]];
        if (!prop) {
          continue;
        }
        propFloatOffset += emitPropBox(propUpload, propFloatOffset, prop);
      }
      const propVertexCount = propFloatOffset / PROP_FLOATS_PER_VERTEX;

      gl.useProgram(propProgram);
      gl.bindBuffer(gl.ARRAY_BUFFER, propVbo);
      gl.enableVertexAttribArray(0);
      gl.vertexAttribPointer(
        0,
        3,
        gl.FLOAT,
        false,
        PROP_FLOATS_PER_VERTEX * 4,
        0,
      );
      gl.enableVertexAttribArray(1);
      gl.vertexAttribPointer(
        1,
        3,
        gl.FLOAT,
        false,
        PROP_FLOATS_PER_VERTEX * 4,
        3 * 4,
      );
      if (propViewProjectionLoc) {
        gl.uniformMatrix4fv(propViewProjectionLoc, false, state.viewProjection);
      }
      gl.enable(gl.DEPTH_TEST);
      gl.depthMask(true);
      gl.disable(gl.BLEND);
      if (propVertexCount > 0) {
        gl.bufferSubData(gl.ARRAY_BUFFER, 0, propUpload, 0, propFloatOffset);
        gl.drawArrays(gl.TRIANGLES, 0, propVertexCount);
      }

      // Blended public/agent billboards: far-to-near for correct alpha.
      const billboardBudget = MAX_BILLBOARDS - visiblePropCount;
      const visibleBillboardCount = billboardBudget > 0
        ? selectVisibleDecorationsForCamera(
            scene.billboards,
            state.cameraWorld,
            NEATRACING_DECORATION_CULL_DISTANCE_M,
            billboardBudget,
            billboardScratch,
          )
        : 0;
      const billboardVertexCount = buildBillboardUpload(
        billboardUpload,
        scene.billboards,
        scene.atlas.frames,
        uvs,
        frameIdToIndex,
        visibleBillboardCount,
        billboardScratch,
        state.cameraRight,
        state.cameraUp,
      );
      if (billboardVertexCount > 0) {
        gl.useProgram(billboardProgram);
        gl.bindBuffer(gl.ARRAY_BUFFER, billboardVbo);
        gl.bufferSubData(
          gl.ARRAY_BUFFER,
          0,
          billboardUpload,
          0,
          billboardVertexCount * BILLBOARD_FLOATS_PER_VERTEX,
        );
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(
          0,
          3,
          gl.FLOAT,
          false,
          BILLBOARD_FLOATS_PER_VERTEX * 4,
          0,
        );
        gl.enableVertexAttribArray(1);
        gl.vertexAttribPointer(
          1,
          2,
          gl.FLOAT,
          false,
          BILLBOARD_FLOATS_PER_VERTEX * 4,
          3 * 4,
        );
        if (billboardViewProjectionLoc) {
          gl.uniformMatrix4fv(
            billboardViewProjectionLoc,
            false,
            state.viewProjection,
          );
        }
        if (billboardAtlasLoc) {
          gl.uniform1i(billboardAtlasLoc, 0);
        }
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_2D, atlasTexture);
        gl.depthMask(false);
        gl.enable(gl.BLEND);
        gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
        gl.drawArrays(gl.TRIANGLES, 0, billboardVertexCount);
        gl.depthMask(true);
        gl.disable(gl.BLEND);
      }
    },
    dispose: (): void => {
      gl.deleteProgram(propProgram);
      gl.deleteProgram(billboardProgram);
      gl.deleteShader(propVertexShader);
      gl.deleteShader(propFragmentShader);
      gl.deleteShader(billboardVertexShader);
      gl.deleteShader(billboardFragmentShader);
      gl.deleteBuffer(propVbo);
      gl.deleteBuffer(billboardVbo);
      gl.deleteTexture(atlasTexture);
    },
  };
}
